using handler = void (*)(g6_native_ctx*);
using resolver = handler (*)(std::uint64_t);

inline resolver g_resolver = nullptr;
inline void set_resolver(resolver r) noexcept { g_resolver = r; }

template <typename T> inline std::uint64_t to_slot(T v) noexcept {
    if constexpr (std::is_same_v<T, float>) { std::uint32_t u; std::memcpy(&u, &v, 4); return u; }
    else if constexpr (std::is_same_v<T, double>) { std::uint64_t u; std::memcpy(&u, &v, 8); return u; }
    else if constexpr (std::is_pointer_v<T>) return reinterpret_cast<std::uint64_t>(v);
    else return static_cast<std::uint64_t>(v);
}

template <typename R> inline R from_slot(const std::uint64_t* ret) noexcept {
    if constexpr (std::is_same_v<R, void>) { return; }
    else if constexpr (std::is_same_v<R, g6_entity>) { return g6_entity{ ret[0], ret[1] }; }
    else if constexpr (std::is_same_v<R, g6_vec3>) { return g6_ret_vec3_packed(ret); }
    else if constexpr (std::is_same_v<R, float>) { std::uint32_t u = static_cast<std::uint32_t>(ret[0]); float f; std::memcpy(&f, &u, 4); return f; }
    else if constexpr (std::is_same_v<R, double>) { double d; std::memcpy(&d, ret, 8); return d; }
    else if constexpr (std::is_pointer_v<R>) return reinterpret_cast<R>(ret[0]);
    else return static_cast<R>(ret[0]);
}

template <typename R = void, typename... Args>
inline R invoke(std::uint64_t hash, Args... args) noexcept {
    const std::uint64_t slots[] = { to_slot(args)..., 0 };
    std::uint64_t ret[4] = { 0, 0, 0, 0 };
    g6_native_ctx ctx{ const_cast<std::uint64_t*>(slots), ret, static_cast<std::int32_t>(sizeof...(Args)), 0 };
    if (handler h = g_resolver ? g_resolver(hash) : nullptr) h(&ctx);
    return from_slot<R>(ret);
}

/* Raw path for untyped natives: caller supplies u64 slots and a ret buffer. */
inline std::uint32_t invoke_raw(std::uint64_t hash, const std::uint64_t* args, std::int32_t argc,
                                std::uint64_t* ret, std::uint32_t ret_count = 0) noexcept {
    g6_native_ctx ctx{ const_cast<std::uint64_t*>(args), ret, argc, ret_count };
    if (handler h = g_resolver ? g_resolver(hash) : nullptr) h(&ctx);
    return ctx.retCount;
}

